namespace ghidra.app.plugin.core.script;







using docking;
using docking;
using docking.widgets;
using docking.widgets.list;
using ghidra.app.script;
using ghidra.app.script;
using ghidra.util;

public class PickProviderDialog : DialogComponentProvider {
	private static string lastSelectedProviderDescription;

	private List<GhidraScriptProvider> providers;
	private ListPanel<GhidraScriptProvider> listPanel;
	private JComponent parent;
	private bool wasCancelled;

	PickProviderDialog(JComponent parent, HelpLocation help) : base("New Script: Type")
    {
		this.parent = parent;

		providers = GhidraScriptUtil.getProviders();
		DefaultListModel<GhidraScriptProvider> listModel = new();
		foreach (GhidraScriptProvider provider in providers) {
			listModel.addElement(provider);
		}

		addWorkPanel(buildWorkPanel(listModel));
		addOKButton();
		addCancelButton();

		rootPanel.setPreferredSize(new Dimension(300, 225));
		setHelpLocation(help);
	}

	/**
	 * Constructor used in testing only!
	 * 
	 * @param testItems values to populate model with
	 * @param defaultItem the default selection
	 */
	public PickProviderDialog(List<GhidraScriptProvider> testItems,
			GhidraScriptProvider defaultItem) : base("New Script: Type")
    {

		DefaultListModel<GhidraScriptProvider> listModel = new();
		foreach (GhidraScriptProvider item in testItems) {
			listModel.addElement(item);
		}

		addWorkPanel(buildWorkPanel(listModel));
		addOKButton();
		addCancelButton();

		rootPanel.setPreferredSize(new Dimension(300, 225));

		if (defaultItem != null) {
			listPanel.setSelectedValue(defaultItem);
		}
	}

	/**
	 * For testing...
	 * 
	 * @param provider the provider selection 
	 */
	void setSelectedProvider(GhidraScriptProvider provider) {
		listPanel.setSelectedValue(provider);
	}

	GhidraScriptProvider getSelectedProvider() {
		if (providers.size() == 1) {
			return providers.get(0);
		}

		selectBestProvider();

		DockingWindowManager.showDialog(parent, this);
		if (wasCancelled) {
			return null;
		}
		return listPanel.getSelectedValue();
	}

	private void selectBestProvider() {
		if (lastSelectedProviderDescription != null) {
			foreach (GhidraScriptProvider provider in providers) {
				if (provider.getDescription().equals(lastSelectedProviderDescription)) {
					listPanel.setSelectedValue(provider);
					return;
				}
			}
		}

		foreach (GhidraScriptProvider provider in providers) {
			if ("Java".equals(provider.getDescription())) {
				listPanel.setSelectedValue(provider);
				return;
			}
		}
	}

	/* @Override */
	protected void cancelCallback() {
		wasCancelled = true;
		base.cancelCallback();
	}

	/* @Override */
	protected void okCallback() {
		GhidraScriptProvider provider = listPanel.getSelectedValue();
		if (provider != null) {
			lastSelectedProviderDescription = provider.getDescription();
		}
		close();
	}

	private JPanel buildWorkPanel(DefaultListModel<GhidraScriptProvider> listModel) {
		listPanel = new();
		listPanel.setListModel(listModel);
		listPanel.setSelectionMode(ListSelectionModel.SINGLE_SELECTION);
		listPanel.setSelectedIndex(0);
		listPanel.setDoubleClickActionListener(e => close());
		JPanel workPanel = new JPanel(new BorderLayout());
		MultiLineLabel mll = new MultiLineLabel("\nPlease select a script type:");
		workPanel.add(mll, BorderLayout.NORTH);
		workPanel.add(listPanel, BorderLayout.CENTER);
		return workPanel;
	}

}
